  "*** Begin Patch",
  "*** Update File: /Users/lorenzkrinner/conductor/workspaces/ehl_hack/montreal/docs/PLAN.md",
  "@@",
  ...lines.map((line, index) => index === 1 ? ` ${line}` : `-${line}`),
  "*** End Patch",
];
text(await tools.apply_patch(patchLines.join("\n")));

